mapper.select:
select f.batchCode, f.publishType, f.status, f.remark, f.createdAt, f.publishedAt from ( select g.batch_code as batchCode, g.publish_type as publishType, g.remark as remark, g.created_at as createdAt, g.published_at as publishedAt, case when g.publish_status in ('PUBLISHED', 'PUBLISH_FAILED') then g.publish_status when g.approval_status is null or g.approval_status = 'PENDING' then 'PENDING_APPROVAL' else g.approval_status end as status from ( select pr.batch_code, max(pr.publish_type) as publish_type, max(pr.status) as publish_status, max(pr.remark) as remark, max(pr.created_at) as created_at, max(pr.published_at) as published_at, (select ar.status from t_r_approval_record ar where ar.resource_code = pr.batch_code and ar.resource_type in ('WORKFLOW_PUBLISH', 'PROJECT_PUBLISH') order by ar.id desc limit 1) as approval_status from t_r_publish_record pr where pr.project_code = #{projectCode} group by pr.batch_code ) g ) f
f.status = #{status}
order by f.createdAt desc

select pr.batch_code as batchCode, wd.name as workflowName, pr.version_no as versionNo, pr.status from t_r_publish_record pr left join t_r_workflow_definition wd on wd.code = pr.workflow_definition_code where pr.batch_code in
#{code}
order by pr.id
